(31324,'en','Int_Desc_Woocommerce','Sync products, stock levels and orders with your WooCommerce store.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31325,'en','Int_Desc_Shopify','Multi-store sync of products, inventory, orders and customers with Shopify.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31326,'en','Int_Desc_Jumia','Push prices & stock to Jumia Seller Center and import marketplace orders.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31327,'en','Int_Desc_Zapier','Automate workflows: connect Stocky events to thousands of apps.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31328,'en','Int_Desc_Salla','Sync products, stock and orders with your Salla store (Gulf ecommerce).',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31329,'en','Int_Desc_Prestashop','Sync products, stock and orders with your PrestaShop store.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31330,'en','Int_Desc_Mailchimp','Keep a Mailchimp audience in sync with your customers for email campaigns.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31331,'en','Int_Desc_Slack','Post sales, stock alerts and payment events into a Slack channel.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31332,'en','Int_Desc_Telegram','Send business events to a Telegram chat or group via your bot.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31333,'en','Int_Desc_Whatsapp','Send invoices, receipts and automated notifications over WhatsApp.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31334,'en','Int_Desc_Webhooks','Push sales, purchases, payments and stock events to any endpoint.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31335,'en','Int_Desc_Google_Sheets','Export sales, products and customers into a live spreadsheet.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31336,'en','Int_Desc_Xero','Push customers as contacts and sales as invoices into Xero.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31337,'en','Int_Desc_Couriers','Book shipments with courier companies and track delivery, returns & COD.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31338,'en','Int_Desc_Quickbooks','Sync sales, payments and expenses with QuickBooks Online.',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31339,'en','Int_N_Store_Connected','{n} store connected',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
(31340,'en','Int_N_Stores_Connected','{n} stores connected',1,'2026-10-20 00:29:25.000000','2026-10-20 00:29:25.000000'),
